import os
import re

placeholders = set()
for root, dirs, files in os.walk('/tmp/hwpx_work/template_extracted'):
    for f in files:
        path = os.path.join(root, f)
        try:
            with open(path, 'r', encoding='utf-8') as file:
                content = file.read()
                matches = re.findall(r'\{\{[^}]+\}\}', content)
                if matches:
                    print(f'{path}:')
                    for m in matches:
                        print(f'  {m}')
                        placeholders.add(m)
        except:
            pass
print('\nAll unique placeholders:', placeholders)
"
